//! `cargo xtask catalogue check <entry>` (design §4.6): an entry's parity contract run for real.
//! Each case becomes a small lab (`isoloom_catalogue::conformance`), generated by this
//! checkout's `isoloom`, then run through the Isothrum CLI (`up`, `check --json`, `down`) on a
//! container target (`docker`) and a VM target (`vagrant`, on `--provider`). A case passes when
//! every check passes in both forms and every fact reads the same in both. There is no Cargo
//! dependency on Isothrum: its CLI is found on `PATH` or given with `--runner`, so the
//! repositories still depend one way. Writing `conformance.json` and the catalogue page is the
//! conformance unit's (4.6); this is the runner they wire up.

use std::path::{Path, PathBuf};
use std::process::ExitCode;

use isoloom_catalogue::conformance::{CaseVerdict, CheckOutcome, ConformanceLab, Form, LabError, verdict};
use isoloom_catalogue::{CaseName, Catalogue, Entry, Release, Version, pick};
use isoloom_spec::syntax::OsRef;

use super::harness::{self, Runner};
use crate::{Res, process, repo};

/// The arguments of `cargo xtask catalogue check`.
#[derive(clap::Args)]
pub(crate) struct Args {
    /// The entry whose contract runs (`nginx`).
    entry: String,
    /// The release (default: the entry's default); a prefix picks the newest it starts.
    #[arg(long)]
    release: Option<String>,
    /// The OS (default: the release's first).
    #[arg(long)]
    os: Option<String>,
    /// The forms to run: `container`, `vm` or `both` (parity needs both).
    #[arg(long, default_value = "both")]
    form: Forms,
    /// The cases to run (default: every case).
    #[arg(long)]
    case: Vec<String>,
    /// The Isothrum CLI (default: `isothrum` on `PATH`).
    #[arg(long)]
    runner: Option<PathBuf>,
    /// The Vagrant provider of the VM form (default: `virtualbox`, `libvirt` on Linux).
    #[arg(long)]
    provider: Option<String>,
    /// Leave each lab running after its checks (its folder says how to reach it).
    #[arg(long)]
    keep: bool,
}

/// The forms a check runs.
#[derive(Debug, Clone, Copy, PartialEq, Eq, clap::ValueEnum)]
enum Forms {
    /// The container form only.
    Container,
    /// The VM form only.
    Vm,
    /// Both: the parity contract's claim.
    Both,
}

impl Forms {
    /// Whether `form` runs.
    fn has(self, form: Form) -> bool {
        matches!((self, form), (Forms::Both, _) | (Forms::Container, Form::Container) | (Forms::Vm, Form::Vm))
    }
}

/// Runs the entry's contract; exit 1 when a case fails.
pub(crate) fn run(args: &Args) -> Res<ExitCode> {
    let root = repo::root();
    let catalogue = on_disk(&root.join("catalogue"))?;
    let entry = catalogue
        .entry(&args.entry)
        .ok_or_else(|| format!("the catalogue has no entry `{}`", args.entry))?;
    let release = release(entry, args.release.as_deref())?;
    let os: OsRef = match &args.os {
        Some(os) => os.parse()?,
        None => *release.os.first().ok_or("the release lists no OS")?,
    };
    let runner = Runner {
        isoloom: harness::isoloom(&root)?,
        isothrum: args
            .runner
            .clone()
            .unwrap_or_else(|| process::program("isothrum", &std::env::var_os("PATH").unwrap_or_default()).into()),
        work: repo::target_dir(&root).join("catalogue-check").join(entry.name().as_str()),
        provider: args
            .provider
            .clone()
            .unwrap_or_else(|| if cfg!(target_os = "linux") { "libvirt" } else { "virtualbox" }.to_owned()),
        keep: args.keep,
    };
    println!(
        "catalogue check: {} {} on {os}, {:?} form(s), runner {}",
        entry.name(),
        release.version,
        args.form,
        runner.isothrum.display()
    );
    let mut failed = 0;
    for case in cases(entry, &args.case)? {
        let lab = match entry.conformance_lab(&catalogue, &case, release, os) {
            Ok(lab) => lab,
            Err(skip @ LabError::MissingEntry { .. }) => {
                println!("catalogue check: {case}: skipped: {skip}");
                continue;
            }
            Err(e) => return Err(e.into()),
        };
        let v = run_case(&runner, &case, &lab, args.form)?;
        report(&case, &v, args.form);
        let ok = if args.form == Forms::Both { v.passed() } else { v.passed_where_run() };
        failed += usize::from(!ok);
    }
    Ok(if failed == 0 { ExitCode::SUCCESS } else { ExitCode::FAILURE })
}

/// The catalogue as it is on disk (the entries being worked on, not the ones built in).
fn on_disk(dir: &Path) -> Res<Catalogue> {
    let mut files = Vec::new();
    collect(dir, dir, &mut files)?;
    Ok(Catalogue::from_files(files.iter().map(|(p, t)| (p.as_str(), t.as_str())))?)
}

/// Every text file under `dir`, by its path from `root`.
fn collect(root: &Path, dir: &Path, out: &mut Vec<(String, String)>) -> Res<()> {
    for e in std::fs::read_dir(dir)? {
        let path = e?.path();
        if path.is_dir() {
            collect(root, &path, out)?;
        } else if let Ok(text) = std::fs::read_to_string(&path) {
            out.push((repo::slashed(path.strip_prefix(root)?), text));
        }
    }
    Ok(())
}

/// The release `asked` picks (the default when `None`).
fn release<'a>(entry: &'a Entry, asked: Option<&str>) -> Res<&'a Release> {
    let def = entry.definition();
    let version: Version = asked.map_or_else(|| Ok(def.default.clone()), str::parse)?;
    let picked = pick(def.releases.iter().map(|r| &r.version), &version)
        .ok_or_else(|| format!("{} has no release `{version}`: {}", entry.name(), def.releases_list()))?;
    def.release(picked).ok_or_else(|| "a picked release is listed".into())
}

/// The cases to run: those asked, else every case.
fn cases(entry: &Entry, asked: &[String]) -> Res<Vec<CaseName>> {
    let all: Vec<CaseName> = entry.contract().cases.keys().cloned().collect();
    if asked.is_empty() {
        return Ok(all);
    }
    asked
        .iter()
        .map(|a| {
            all.iter()
                .find(|c| c.as_str() == a)
                .cloned()
                .ok_or_else(|| format!("the contract has no case `{a}`").into())
        })
        .collect()
}

/// Case `case` run in the forms asked, and its verdict.
fn run_case(runner: &Runner, case: &CaseName, lab: &ConformanceLab, forms: Forms) -> Res<CaseVerdict> {
    let dir = runner.work.join(case.as_str());
    harness::write_lab(&dir, lab)?;
    let container = forms.has(Form::Container).then(|| runner.run(&dir, Form::Container)).transpose()?;
    let vm = forms.has(Form::Vm).then(|| runner.run(&dir, Form::Vm)).transpose()?;
    Ok(verdict(lab, container.as_ref(), vm.as_ref()))
}

/// The case's verdict, a line per check and fact.
fn report(case: &CaseName, v: &CaseVerdict, forms: Forms) {
    let word = |o: &CheckOutcome| match o {
        CheckOutcome::Passed => "pass".to_owned(),
        CheckOutcome::Failed(why) => format!("FAIL ({why})"),
        CheckOutcome::Missing => "FAIL (not reported)".to_owned(),
        _ => "-".to_owned(),
    };
    for c in &v.checks {
        println!("  {case}: {}: container {}, vm {}", c.name, word(&c.container), word(&c.vm));
    }
    for f in &v.facts {
        let mark = if f.equal() { "equal" } else { "DIFFER" };
        println!("  {case}: fact {}: container {:?}, vm {:?}: {mark}", f.name, f.container, f.vm);
    }
    let passed = if forms == Forms::Both { v.passed() } else { v.passed_where_run() };
    println!("catalogue check: {case}: {}", if passed { "PASS" } else { "FAIL" });
}
